#define _GNU_SOURCE

#include <dlfcn.h>
#include <errno.h>
#include <fcntl.h>
#include <pthread.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <unistd.h>

#define HEADER "# SSL key log file generated by sslkeylogfile.c\n"
#define FILENAME_ENVVAR "LIBSSL_SSLKEYLOGFILE"
/* SSL_CTX_get_ex_new_index is this macro in OpenSSL 1.1.1 and 3.x. */
#define CRYPTO_EX_INDEX_SSL_CTX 1

/* Resolve the public OpenSSL ABI at runtime; the build needs no OpenSSL headers. */
typedef struct ssl_st SSL;
typedef struct ssl_ctx_st SSL_CTX;
typedef struct crypto_ex_data_st CRYPTO_EX_DATA;
typedef void (*ssl_keylog_cb_fn)(const SSL *ssl, const char *line);
typedef SSL *(*ssl_new_fn)(SSL_CTX *ctx);
typedef SSL_CTX *(*ssl_set_ssl_ctx_fn)(SSL *ssl, SSL_CTX *ctx);
typedef SSL_CTX *(*ssl_get_ssl_ctx_fn)(const SSL *ssl);
typedef void (*ssl_ctx_set_keylog_callback_fn)(SSL_CTX *ctx, ssl_keylog_cb_fn cb);
typedef ssl_keylog_cb_fn (*ssl_ctx_get_keylog_callback_fn)(const SSL_CTX *ctx);
typedef int (*ssl_ctx_set_ex_data_fn)(SSL_CTX *ctx, int index, void *data);
typedef void *(*ssl_ctx_get_ex_data_fn)(const SSL_CTX *ctx, int index);
typedef void crypto_ex_new_fn(void *, void *, CRYPTO_EX_DATA *, int, long, void *);
typedef void crypto_ex_free_fn(void *, void *, CRYPTO_EX_DATA *, int, long, void *);
typedef int crypto_ex_dup_fn(CRYPTO_EX_DATA *, const CRYPTO_EX_DATA *, void **, int, long, void *);
typedef int (*crypto_get_ex_new_index_fn)(int, long, void *, crypto_ex_new_fn *,
  crypto_ex_dup_fn *, crypto_ex_free_fn *);

struct keylog_context {
  ssl_keylog_cb_fn callback;
};

static pthread_once_t resolve_symbols_once = PTHREAD_ONCE_INIT;
static pthread_mutex_t keylog_mutex = PTHREAD_MUTEX_INITIALIZER;
static ssl_new_fn real_SSL_new = NULL;
static ssl_set_ssl_ctx_fn real_SSL_set_SSL_CTX = NULL;
static ssl_get_ssl_ctx_fn real_SSL_get_SSL_CTX = NULL;
static ssl_ctx_set_keylog_callback_fn real_SSL_CTX_set_keylog_callback = NULL;
static ssl_ctx_get_keylog_callback_fn real_SSL_CTX_get_keylog_callback = NULL;
static ssl_ctx_set_ex_data_fn real_SSL_CTX_set_ex_data = NULL;
static ssl_ctx_get_ex_data_fn real_SSL_CTX_get_ex_data = NULL;
static void *libssl_handle = NULL;
static int context_index = -1;
static int fd_sslkeylogfile = -1;
static int keylog_disabled = 0;
static int keylog_warning_emitted = 0;

static void resolve_symbols(void);
static void warn_keylog_disabled_locked(const char *message);
static void disable_keylog_locked(const char *message);
static void open_sslkeylogfile_locked(void);
static void write_sslkeylogfile(const SSL *ssl, const char *line);
static struct keylog_context *install_callback_locked(SSL_CTX *ctx);

static void before_fork(void) {
  pthread_mutex_lock(&keylog_mutex);
}

static void after_fork(void) {
  pthread_mutex_unlock(&keylog_mutex);
}

__attribute__((constructor)) static void initialize_keylog(void) {
  int status = pthread_atfork(before_fork, after_fork, after_fork);
  char message[256];

  if (status != 0) {
    snprintf(message, sizeof(message), "failed to register fork handlers: %s", strerror(status));
    disable_keylog_locked(message);
    return;
  }

  /* Open while the master still has permission to traverse the private directory.
   * Workers inherit the append-only descriptor across fork, including after setuid.
   * CLOEXEC prevents leaking it into unrelated programs; a preloaded exec reopens it. */
  pthread_mutex_lock(&keylog_mutex);
  open_sslkeylogfile_locked();
  pthread_mutex_unlock(&keylog_mutex);
}

__attribute__((destructor)) static void close_keylog(void) {
  pthread_mutex_lock(&keylog_mutex);
  keylog_disabled = 1;
  if (fd_sslkeylogfile != -1) {
    close(fd_sslkeylogfile);
    fd_sslkeylogfile = -1;
  }
  pthread_mutex_unlock(&keylog_mutex);
}

SSL *SSL_new(SSL_CTX *ctx) {
  pthread_once(&resolve_symbols_once, resolve_symbols);
  if (real_SSL_new == NULL) {
    fprintf(stderr, "TLS keylog helper fatal: could not resolve real SSL_new\n");
    fflush(stderr);
    _exit(127);
  }

  pthread_mutex_lock(&keylog_mutex);
  install_callback_locked(ctx);
  pthread_mutex_unlock(&keylog_mutex);
  return real_SSL_new(ctx);
}

SSL_CTX *SSL_set_SSL_CTX(SSL *ssl, SSL_CTX *ctx) {
  SSL_CTX *active_ctx;

  pthread_once(&resolve_symbols_once, resolve_symbols);
  if (real_SSL_set_SSL_CTX == NULL) {
    fprintf(stderr, "TLS keylog helper fatal: could not resolve real SSL_set_SSL_CTX\n");
    fflush(stderr);
    _exit(127);
  }

  active_ctx = real_SSL_set_SSL_CTX(ssl, ctx);
  /* Nginx selects the virtual host during SNI. OpenSSL logs through that context,
   * which may never have been passed to SSL_new (including a NULL-context reset). */
  pthread_mutex_lock(&keylog_mutex);
  install_callback_locked(active_ctx);
  pthread_mutex_unlock(&keylog_mutex);
  return active_ctx;
}

void SSL_CTX_set_keylog_callback(SSL_CTX *ctx, ssl_keylog_cb_fn cb) {
  struct keylog_context *data;

  pthread_once(&resolve_symbols_once, resolve_symbols);
  if (real_SSL_CTX_set_keylog_callback == NULL) {
    return;
  }
  pthread_mutex_lock(&keylog_mutex);
  data = install_callback_locked(ctx);
  if (data != NULL) {
    if (cb != write_sslkeylogfile) {
      data->callback = cb;
    }
    real_SSL_CTX_set_keylog_callback(ctx, write_sslkeylogfile);
  } else {
    real_SSL_CTX_set_keylog_callback(ctx, cb);
  }
  pthread_mutex_unlock(&keylog_mutex);
}

ssl_keylog_cb_fn SSL_CTX_get_keylog_callback(const SSL_CTX *ctx) {
  struct keylog_context *data = NULL;
  ssl_keylog_cb_fn callback = NULL;

  pthread_once(&resolve_symbols_once, resolve_symbols);
  pthread_mutex_lock(&keylog_mutex);
  if (ctx != NULL && context_index >= 0) {
    data = real_SSL_CTX_get_ex_data(ctx, context_index);
  }
  if (data != NULL) {
    callback = data->callback;
  } else if (real_SSL_CTX_get_keylog_callback != NULL) {
    callback = real_SSL_CTX_get_keylog_callback(ctx);
  }
  pthread_mutex_unlock(&keylog_mutex);
  return callback;
}

static void free_context(void *parent, void *ptr, CRYPTO_EX_DATA *ad, int index,
  long argl, void *argp) {
  (void)parent;
  (void)ad;
  (void)index;
  (void)argl;
  (void)argp;
  free(ptr);
}

static int symbol_is_helper(void *symbol) {
  Dl_info candidate, helper;

  /* Comparing against the exported SSL_new can compare with the real function
   * when this library is dlopened after libssl and its symbols are preempted. */
  return symbol != NULL && dladdr(symbol, &candidate) != 0 &&
    dladdr((void *)resolve_symbols, &helper) != 0 && candidate.dli_fbase == helper.dli_fbase;
}

static void *find_ssl_symbol(const char *name) {
  void *symbol = dlsym(RTLD_NEXT, name);

  if (symbol == NULL || symbol_is_helper(symbol)) {
    symbol = dlsym(RTLD_DEFAULT, name);
  }
  if ((symbol == NULL || symbol_is_helper(symbol)) && libssl_handle != NULL) {
    symbol = dlsym(libssl_handle, name);
  }
  return symbol_is_helper(symbol) ? NULL : symbol;
}

static void resolve_symbols(void) {
  const char *libraries[] = {"libssl.so.3", "libssl.so.1.1", "libssl.so"};
  crypto_get_ex_new_index_fn new_index;
  size_t i;

  real_SSL_new = (ssl_new_fn)find_ssl_symbol("SSL_new");
  for (i = 0; real_SSL_new == NULL && i < sizeof(libraries) / sizeof(libraries[0]); i++) {
    libssl_handle = dlopen(libraries[i], RTLD_NOW | RTLD_LOCAL);
    if (libssl_handle != NULL) {
      real_SSL_new = (ssl_new_fn)find_ssl_symbol("SSL_new");
      if (real_SSL_new == NULL) {
        dlclose(libssl_handle);
        libssl_handle = NULL;
      }
    }
  }

  real_SSL_set_SSL_CTX = (ssl_set_ssl_ctx_fn)find_ssl_symbol("SSL_set_SSL_CTX");
  real_SSL_get_SSL_CTX = (ssl_get_ssl_ctx_fn)find_ssl_symbol("SSL_get_SSL_CTX");
  real_SSL_CTX_set_keylog_callback =
    (ssl_ctx_set_keylog_callback_fn)find_ssl_symbol("SSL_CTX_set_keylog_callback");
  real_SSL_CTX_get_keylog_callback =
    (ssl_ctx_get_keylog_callback_fn)find_ssl_symbol("SSL_CTX_get_keylog_callback");
  real_SSL_CTX_set_ex_data = (ssl_ctx_set_ex_data_fn)find_ssl_symbol("SSL_CTX_set_ex_data");
  real_SSL_CTX_get_ex_data = (ssl_ctx_get_ex_data_fn)find_ssl_symbol("SSL_CTX_get_ex_data");
  new_index = (crypto_get_ex_new_index_fn)find_ssl_symbol("CRYPTO_get_ex_new_index");

  if (real_SSL_CTX_set_keylog_callback != NULL && real_SSL_CTX_get_keylog_callback != NULL &&
    real_SSL_get_SSL_CTX != NULL && real_SSL_CTX_set_ex_data != NULL &&
    real_SSL_CTX_get_ex_data != NULL && new_index != NULL) {
    context_index = new_index(CRYPTO_EX_INDEX_SSL_CTX, 0, NULL, NULL, NULL, free_context);
  }
  if (context_index < 0) {
    pthread_mutex_lock(&keylog_mutex);
    disable_keylog_locked("OpenSSL keylog callback support is unavailable");
    pthread_mutex_unlock(&keylog_mutex);
  }
}

static struct keylog_context *install_callback_locked(SSL_CTX *ctx) {
  struct keylog_context *data;
  ssl_keylog_cb_fn current;

  if (ctx == NULL || context_index < 0) {
    return NULL;
  }
  data = real_SSL_CTX_get_ex_data(ctx, context_index);
  if (data == NULL && (keylog_disabled || fd_sslkeylogfile == -1)) {
    return NULL;
  }
  current = real_SSL_CTX_get_keylog_callback(ctx);
  if (data == NULL) {
    data = malloc(sizeof(*data));
    if (data == NULL) {
      disable_keylog_locked("failed to allocate callback state");
      return NULL;
    }
    data->callback = current;
    if (!real_SSL_CTX_set_ex_data(ctx, context_index, data)) {
      free(data);
      disable_keylog_locked("failed to attach callback state");
      return NULL;
    }
  }
  if (current != write_sslkeylogfile) {
    data->callback = current;
    real_SSL_CTX_set_keylog_callback(ctx, write_sslkeylogfile);
  }
  return data;
}

static void warn_keylog_disabled_locked(const char *message) {
  if (!keylog_warning_emitted) {
    fprintf(stderr, "TLS keylog helper disabled: %s\n", message);
    keylog_warning_emitted = 1;
  }
}

static void disable_keylog_locked(const char *message) {
  if (fd_sslkeylogfile != -1) {
    close(fd_sslkeylogfile);
    fd_sslkeylogfile = -1;
  }
  keylog_disabled = 1;
  warn_keylog_disabled_locked(message);
}

static int open_keylog_path(const char *filename) {
  char *path = strdup(filename), *part, *next, *rest = NULL;
  int dirfd = -1, nextfd, fd = -1, saved_errno;
  struct stat st;

  if (path == NULL) {
    return -1;
  }
  dirfd = open(filename[0] == '/' ? "/" : ".", O_RDONLY | O_DIRECTORY | O_CLOEXEC);
  if (dirfd == -1) {
    goto done;
  }
  part = strtok_r(path, "/", &rest);
  if (part == NULL) {
    errno = EINVAL;
    goto done;
  }
  while (part != NULL) {
    next = strtok_r(NULL, "/", &rest);
    if (strcmp(part, "..") == 0 || (next == NULL && strcmp(part, ".") == 0)) {
      errno = EINVAL;
      goto done;
    }
    if (next == NULL) {
      /* NONBLOCK avoids hanging on a FIFO before fstat rejects it. Every path
       * component is opened without following symlinks, including the leaf. */
      fd = openat(dirfd, part, O_WRONLY | O_APPEND | O_CREAT | O_NOFOLLOW |
        O_NONBLOCK | O_CLOEXEC, S_IRUSR | S_IWUSR);
      if (fd != -1) {
        if (fstat(fd, &st) != 0) {
          saved_errno = errno;
          close(fd);
          fd = -1;
          errno = saved_errno;
        } else if (!S_ISREG(st.st_mode) || st.st_nlink != 1) {
          close(fd);
          fd = -1;
          errno = EINVAL;
        }
      }
      break;
    }
    nextfd = openat(dirfd, part, O_RDONLY | O_DIRECTORY | O_NOFOLLOW | O_CLOEXEC);
    if (nextfd == -1) {
      goto done;
    }
    close(dirfd);
    dirfd = nextfd;
    part = next;
  }

done:
  saved_errno = errno;
  if (dirfd != -1) {
    close(dirfd);
  }
  free(path);
  errno = saved_errno;
  return fd;
}

static void open_sslkeylogfile_locked(void) {
  const char *filename = getenv(FILENAME_ENVVAR);
  char message[512];
  struct stat st;
  ssize_t written;

  if (filename == NULL || *filename == '\0') {
    filename = getenv("SSLKEYLOGFILE");
  }
  if (filename == NULL || *filename == '\0') {
    disable_keylog_locked("neither LIBSSL_SSLKEYLOGFILE nor SSLKEYLOGFILE is set");
    return;
  }
  fd_sslkeylogfile = open_keylog_path(filename);
  if (fd_sslkeylogfile == -1) {
    snprintf(message, sizeof(message), "failed to safely open %s: %s", filename, strerror(errno));
    disable_keylog_locked(message);
    return;
  }
  if (fstat(fd_sslkeylogfile, &st) != 0) {
    disable_keylog_locked("failed to inspect keylog file");
    return;
  }
  if (st.st_size == 0) {
    written = write(fd_sslkeylogfile, HEADER, sizeof(HEADER) - 1);
    if (written != (ssize_t)(sizeof(HEADER) - 1)) {
      disable_keylog_locked("failed to write complete keylog header");
    }
  }
}

static void write_sslkeylogfile(const SSL *ssl, const char *line) {
  struct keylog_context *data;
  ssl_keylog_cb_fn callback = NULL;
  char message[512];
  char *record = NULL;
  size_t line_len = 0;
  size_t record_len = 0;
  ssize_t written = 0;
  int saved_errno = 0, caller_errno;

  pthread_mutex_lock(&keylog_mutex);
  data = real_SSL_CTX_get_ex_data(real_SSL_get_SSL_CTX(ssl), context_index);
  if (data != NULL) {
    callback = data->callback;
  }
  pthread_mutex_unlock(&keylog_mutex);
  /* Application callbacks may change their callback or use SSL themselves. */
  if (callback != NULL && callback != write_sslkeylogfile) {
    callback(ssl, line);
  }
  caller_errno = errno;

  pthread_mutex_lock(&keylog_mutex);
  if (!keylog_disabled && fd_sslkeylogfile != -1) {
    line_len = strlen(line);
    if (line_len > ((size_t)-1) - 1) {
      disable_keylog_locked("failed to write key material: keylog line is too large");
      goto done;
    }
    record_len = line_len + 1;
    record = malloc(record_len);
    if (record == NULL) {
      disable_keylog_locked("failed to allocate keylog record buffer");
      goto done;
    }
    memcpy(record, line, line_len);
    record[line_len] = '\n';
    /* One append syscall per complete record also protects concurrent workers. */
    written = write(fd_sslkeylogfile, record, record_len);
    saved_errno = errno;
    free(record);
    if (written < 0) {
      snprintf(message, sizeof(message), "failed to write key material: %s", strerror(saved_errno));
      disable_keylog_locked(message);
    } else if ((size_t)written != record_len) {
      snprintf(message, sizeof(message), "failed to write key material: short write (%ld of %lu bytes)",
        (long)written, (unsigned long)record_len);
      disable_keylog_locked(message);
    }
  }

done:
  pthread_mutex_unlock(&keylog_mutex);
  errno = caller_errno;
}
